import heapq
from collections import defaultdict

def sliding_median(nums: list[int], k: int) -> list[float]:
 if k <= 0:
 raise ValueError("k must be positive")
 if not nums or k > len(nums):
 return []

 left = [] # max-heap (store negative values)
 right = [] # min-heap
 removed = defaultdict(int)

 def rebalance():
 # Clean any marked elements at the top of both heaps
 while left or right:
 while left and removed.get(-left[0], 0) > 0:
 val = heapq.heappop(left)
 removed[-val] -= 1
 while right and removed.get(right[0], 0) > 0:
 val = heapq.heappop(right)
 removed[val] -= 1
 # Adjust heap sizes to maintain balance
 if len(left) > len(right) + 1:
 # Move one from left to right
 val = -heapq.heappop(left)
 heapq.heappush(right, val)
 elif len(right) > len(left):
 # Move one from right to left
 val = heapq.heappop(right)
 heapq.heappush(left, -val)

 # Insert the first k elements
 for i in range(k):
 val = nums[i]
 if not left or val < -left[0]:
 heapq.heappush(left, -val)
 else:
 heapq.heappush(right, val)
 rebalance()

 result = []
 if len(left) > len(right):
 result.append(float(-left[0]))
 else:
 result.append((-left[0] + right[0]) / 2.0)

 # Slide the window
 for i in range(k, len(nums)):
 old = nums[i - k]
 new = nums[i]

 # Remove the element that leaves the window
 removed[old] = removed.get(old, 0) + 1
 rebalance()

 # Insert the new element
 if not left or new < -left[0]:
 heapq.heappush(left, -new)
 else:
 heapq.heappush(right, new)
 rebalance()

 if len(left) > len(right):
 result.append(float(-left[0]))
 else:
 result.append((-left[0] + right[0]) / 2.0)

 return result
